//! The regular-expression engine against the behaviour record (spec §14.9; D-14.4), at the
//! library level: every regex line of `spec/behaviour/patterns.glibc.txt.gz` that the `C` and
//! `C.UTF-8` locales produce (the `regcomp` errors, the matching cases, the successive
//! matches, `REG_STARTEND`, the character classes, the locale cases and the four generated
//! corpora) is recomputed through `liella::pattern::regex` in the probe's format and compared
//! with the record. A line may differ from glibc's only where
//! `spec/behaviour/regex-posix.expected.txt` (generated by `spec/tools/regex_posix_reference.py`,
//! the POSIX XBD 9.1 reading the owner ruled for) gives the POSIX line, and then it must be that
//! line exactly. The C interface (`regex_t`, `regerror`, the GNU and BSD interfaces) is covered by
//! the products test, `patterns_products.rs`.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::indexing_slicing, clippy::arithmetic_side_effects, clippy::as_conversions, missing_docs)]

use std::collections::{BTreeMap, HashMap};
use std::fmt::Write as _;
use std::path::PathBuf;

use liella::locale::Locale;
use liella::pattern::regex::{self, cflags, Options, Window};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn record() -> String {
    let gz = std::fs::read(root().join("spec/behaviour/patterns.glibc.txt.gz")).unwrap();
    let raw = liella::charmap::inflate::gunzip(&gz, 64 << 20).unwrap();
    raw.iter().map(|&b| b as char).collect()
}

/// Lines that differ from glibc by decision (see `patterns_products.rs`): a count above
/// RE_DUP_MAX is REG_BADBR (POSIX regcomp, spec §14.9), not REG_ESIZE.
const KNOWN: [(&str, &str); 5] = [
    ("regcomp E [a{32768}] = 15", "regcomp E [a{32768}] = 10"),
    ("regcomp E [a{1,32768}] = 15", "regcomp E [a{1,32768}] = 10"),
    ("regcomp E [a{99999999999}] = 15", "regcomp E [a{99999999999}] = 10"),
    ("re E [a{32768}] [a] - -> regcomp=15", "re E [a{32768}] [a] - -> regcomp=10"),
    ("re E [a{65536}] [a] - -> regcomp=15", "re E [a{65536}] [a] - -> regcomp=10"),
];

/// Lines that differ from glibc by decision in a UTF-8 locale only (the same text in `C` does not
/// differ): a single-character collating element `[[.é.]]` is the character, as POSIX XBD 9.3.5
/// defines (three-way rule, D-14.4; glibc gives REG_ECOLLATE). In `C` the name is two bytes,
/// two characters, and stays REG_ECOLLATE.
const KNOWN_UTF8: [(&str, &str); 1] = [(r"re E [[[.\xc3\xa9.]]] [\xc3\xa9] - -> regcomp=3", r"re E [[[.\xc3\xa9.]]] [\xc3\xa9] - -> 0 nsub=0 (0,2)")];

/// glibc's line -> (categories, the POSIX line).
fn expectations() -> HashMap<String, (String, String)> {
    let text = std::fs::read(root().join("spec/behaviour/regex-posix.expected.txt")).unwrap();
    let text: String = text.iter().map(|&b| b as char).collect();
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| {
            let mut f = l.splitn(3, '\t');
            let (cats, glibc, posix) = (f.next().unwrap(), f.next().unwrap(), f.next().unwrap());
            (glibc.to_string(), (cats.to_string(), posix.to_string()))
        })
        .collect()
}

fn unesc(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'\\' && b.get(i + 1) == Some(&b'x') && i + 3 < b.len() {
            out.push(u8::from_str_radix(&s[i + 2..i + 4], 16).unwrap());
            i += 4;
        } else {
            out.push(b[i]);
            i += 1;
        }
    }
    out
}

fn esc(b: &[u8]) -> String {
    let mut s = String::new();
    for &c in b {
        if c == b'\\' || !(0x20..0x7f).contains(&c) {
            write!(s, "\\x{c:02x}").unwrap();
        } else {
            s.push(c as char);
        }
    }
    s
}

fn flags_of(f: &str) -> i32 {
    let mut cf = 0;
    for c in f.chars() {
        cf |= match c {
            'E' => cflags::EXTENDED,
            'I' => cflags::ICASE,
            'N' => cflags::NEWLINE,
            'S' => cflags::NOSUB,
            _ => 0,
        };
    }
    cf
}

const NOTBOL: i32 = 1;
const NOTEOL: i32 = 2;
const STARTEND: i32 = 4;

/// `regcomp` then `regexec` as the C interface does them: the result code and the `nmatch`
/// entries (`None` entries untouched).
struct Re {
    prog: Result<regex::Program, i32>,
    cf: i32,
}

fn regcomp(pat: &[u8], cf: i32, loc: &Locale) -> Re {
    Re { prog: regex::compile(pat, regex::regcomp_syntax(cf), loc).map_err(regex::regcomp_code), cf }
}

fn regexec(re: &Re, loc: &Locale, buf: &[u8], nmatch: usize, pm: &mut [(i64, i64)], ef: i32) -> i32 {
    let prog = re.prog.as_ref().unwrap();
    let (so, eo) = if ef & STARTEND != 0 { (pm[0].0 as usize, pm[0].1 as usize) } else { (0, buf.len()) };
    if so > eo {
        return 1;
    }
    let subject = &buf[..eo];
    let opts = Options { not_bol: ef & NOTBOL != 0, not_eol: ef & NOTEOL != 0, newline_anchor: re.cf & cflags::NEWLINE != 0, budget: 2000 * regex::BUDGET_PER_FAILURE, ..Options::default() };
    let nosub = re.cf & cflags::NOSUB != 0;
    let r = regex::exec(prog, loc, subject, Window { first: so, last: eo, backward: false }, &opts, !nosub && nmatch > 1).unwrap();
    let Some(m) = r else { return 1 };
    if !nosub && nmatch > 0 {
        pm[0] = (m.start as i64, m.end as i64);
        for (i, slot) in pm.iter_mut().enumerate().take(nmatch).skip(1) {
            *slot = m.groups.get(i - 1).copied().unwrap_or((-1, -1));
        }
    }
    0
}

fn nsub(re: &Re) -> usize {
    re.prog.as_ref().map_or(0, |p| p.nsub())
}

fn re_line(cf_s: &str, pat: &[u8], subj: &[u8], ef_s: &str, loc: &Locale) -> String {
    let cf = flags_of(cf_s);
    let ef = if ef_s == "-" { 0 } else { ef_s.split('|').map(|e| if e == "NOTBOL" { NOTBOL } else if e == "NOTEOL" { NOTEOL } else { 0 }).sum() };
    let mut out = format!("re {cf_s} [{}] [{}] {ef_s}", esc(pat), esc(subj));
    let re = regcomp(pat, cf, loc);
    if let Err(c) = re.prog {
        write!(out, " -> regcomp={c}").unwrap();
        return out;
    }
    let n = (nsub(&re) + 1).min(10);
    let mut m = [(-7i64, -7i64); 10];
    let r = regexec(&re, loc, subj, n, &mut m, ef);
    write!(out, " -> {r} nsub={} ", nsub(&re)).unwrap();
    if r == 0 {
        for (a, b) in &m[..n] {
            write!(out, "({a},{b})").unwrap();
        }
    }
    out
}

fn rc_line(cf_s: &str, pat: &[u8], subjects: &[Vec<u8>], loc: &Locale) -> String {
    let re = regcomp(pat, flags_of(cf_s), loc);
    let mut out = format!("rc {cf_s} [{}]", esc(pat));
    match re.prog {
        Err(c) => write!(out, " {c}").unwrap(),
        Ok(_) => {
            write!(out, " 0 {}", nsub(&re)).unwrap();
            let n = (nsub(&re) + 1).min(10);
            for s in subjects {
                let mut m = [(0i64, 0i64); 10];
                if regexec(&re, loc, s, n, &mut m, 0) != 0 {
                    out.push_str(" -");
                    continue;
                }
                out.push(' ');
                for (i, (a, b)) in m[..n].iter().enumerate() {
                    write!(out, "{}{a}.{b}", if i > 0 { "," } else { "" }).unwrap();
                }
            }
        }
    }
    out
}

fn startend_line(cf_s: &str, pat: &[u8], buf: &[u8], so: i64, eo: i64, ef_s: &str, loc: &Locale) -> String {
    let cf = flags_of(cf_s);
    let mut ef = STARTEND;
    for e in ef_s.split('|') {
        ef |= match e {
            "NOTBOL" => NOTBOL,
            "NOTEOL" => NOTEOL,
            _ => 0,
        };
    }
    let mut out = format!("re-startend {cf_s} [{}] [{}] so={so} eo={eo} {ef_s}", esc(pat), esc(buf));
    let re = regcomp(pat, cf, loc);
    if let Err(c) = re.prog {
        write!(out, " -> regcomp={c}").unwrap();
        return out;
    }
    let n = (nsub(&re) + 1).min(4);
    let mut m = [(-7i64, -7i64); 4];
    m[0] = (so, eo);
    let r = regexec(&re, loc, buf, n, &mut m, ef);
    write!(out, " -> {r} ").unwrap();
    for (a, b) in &m[..n] {
        write!(out, "({a},{b})").unwrap();
    }
    out
}

fn all_line(cf_s: &str, pat: &[u8], subj: &[u8], loc: &Locale) -> String {
    let re = regcomp(pat, flags_of(cf_s), loc);
    let mut out = format!("re-all {cf_s} [{}] [{}]", esc(pat), esc(subj));
    if let Err(c) = re.prog {
        write!(out, " -> regcomp={c}").unwrap();
        return out;
    }
    out.push(' ');
    let (mut pos, mut ef) = (0usize, 0);
    while pos <= subj.len() {
        let n = (nsub(&re) + 1).min(4);
        let mut m = [(0i64, 0i64); 4];
        if regexec(&re, loc, &subj[pos..], n, &mut m, ef) != 0 {
            break;
        }
        for (i, (a, b)) in m[..n].iter().enumerate() {
            let a = if *a < 0 { -1 } else { a + pos as i64 };
            let b = if *b < 0 { -1 } else { b + pos as i64 };
            write!(out, "{}({a},{b})", if i == 0 { " " } else { "" }).unwrap();
        }
        let e = pos + m[0].1 as usize;
        pos = if m[0].1 == m[0].0 { e + 1 } else { e };
        ef = NOTBOL;
    }
    out
}

fn class_line(name: &str, icase: bool, loc: &Locale) -> String {
    let pat = format!("[[:{name}:]]");
    let re = regcomp(pat.as_bytes(), cflags::EXTENDED | cflags::NOSUB | if icase { cflags::ICASE } else { 0 }, loc);
    let mut out = format!("class {name}{}:", if icase { " ICASE" } else { "" });
    let mut start: i32 = -1;
    for b in 1..=256i32 {
        let hit = b < 256 && regexec(&re, loc, &[b as u8], 0, &mut [(0, 0)], 0) == 0;
        if hit && start < 0 {
            start = b;
        }
        if !hit && start >= 0 {
            if start == b - 1 {
                write!(out, " {start:02x}").unwrap();
            } else {
                write!(out, " {start:02x}-{:02x}", b - 1).unwrap();
            }
            start = -1;
        }
    }
    out
}

/// Split `re FLAGS [PAT] [SUBJ] EFLAGS -> ...` into its fields.
fn re_fields(line: &str) -> (String, Vec<u8>, Vec<u8>, String) {
    let head = line.split(" -> ").next().unwrap();
    let rest = head.strip_prefix("re ").unwrap();
    let (flags, rest) = rest.split_once(' ').unwrap();
    let (body, ef) = rest.rsplit_once(' ').unwrap();
    let k = body.rfind("] [").unwrap();
    (flags.to_string(), unesc(&body[1..k]), unesc(&body[k + 3..body.len() - 1]), ef.to_string())
}

#[test]
fn regex_lines_equal_the_record_or_the_posix_reading() {
    // Clauses: s14_9_g_0, s14_9_c_1_1, s14_9_c_1_2, s14_9_f_0 (D-14.4).
    let rec = record();
    let expect = expectations();
    let c = Locale::C;
    let cu = Locale::c_utf8(b"C.UTF-8");
    let mut section = String::new();
    let mut sub = String::new();
    let mut locale: Option<&Locale> = Some(&c);
    let mut subjects: Vec<Vec<u8>> = Vec::new();
    let (mut compared, mut differ, mut by_cat) = (0usize, Vec::new(), BTreeMap::<String, usize>::new());
    for line in rec.lines() {
        if let Some(s) = line.strip_prefix("== ") {
            section = s.to_string();
            sub.clear();
            continue;
        }
        if let Some(name) = line.strip_prefix("-- locale ") {
            locale = match name {
                "C: ok" => Some(&c),
                "C.UTF-8: ok" => Some(&cu),
                _ => None,
            };
            continue;
        }
        if line.starts_with("-- ") {
            sub = line.to_string();
            continue;
        }
        if section != "regex" && section != "regex corpus" {
            continue;
        }
        let Some(loc) = locale else { continue };
        let ours = if line.starts_with("re ") && (sub == "-- matching" || sub == "-- locale dependent") {
            let (f, p, s, e) = re_fields(line);
            re_line(&f, &p, &s, &e, loc)
        } else if let Some(rest) = line.strip_prefix("regcomp ").filter(|_| sub == "-- regcomp errors" && !line.starts_with("regcomp unknown")) {
            let (f, rest) = rest.split_once(' ').unwrap();
            let k = rest.rfind("] = ").unwrap();
            let pat = unesc(&rest[1..k]);
            let re = regcomp(&pat, flags_of(f), loc);
            match re.prog {
                Ok(_) => format!("regcomp {f} [{}] = 0 nsub={}", esc(&pat), nsub(&re)),
                Err(e) => format!("regcomp {f} [{}] = {e}", esc(&pat)),
            }
        } else if let Some(rest) = line.strip_prefix("rc ") {
            let (f, rest) = rest.split_once(' ').unwrap();
            let k = rest.rfind("] ").unwrap();
            rc_line(f, &unesc(&rest[1..k]), &subjects, loc)
        } else if let Some(rest) = line.strip_prefix("subjects ") {
            subjects = rest.split(' ').map(|w| unesc(&w[1..w.len() - 1])).collect();
            continue;
        } else if let Some(rest) = line.strip_prefix("re-startend ") {
            let (f, rest) = rest.split_once(' ').unwrap();
            let k = rest.find("] [").unwrap();
            let pat = unesc(&rest[1..k]);
            let rest = &rest[k + 3..];
            let k = rest.find("] so=").unwrap();
            let buf = unesc(&rest[..k]);
            let nums: Vec<&str> = rest[k + 2..].split(' ').collect();
            let so: i64 = nums[0].strip_prefix("so=").unwrap().parse().unwrap();
            let eo: i64 = nums[1].strip_prefix("eo=").unwrap().parse().unwrap();
            startend_line(f, &pat, &buf, so, eo, nums[2], loc)
        } else if let Some(rest) = line.strip_prefix("re-all ") {
            let (f, rest) = rest.split_once(' ').unwrap();
            let k = rest.find("] [").unwrap();
            let pat = unesc(&rest[1..k]);
            let rest = &rest[k + 3..];
            let k = rest.find(']').unwrap();
            let subj = unesc(&rest[..k]);
            all_line(f, &pat, &subj, loc)
        } else if let Some(rest) = line.strip_prefix("class ") {
            let name = rest.split([' ', ':']).next().unwrap();
            class_line(name, rest.contains(" ICASE:"), loc)
        } else {
            continue;
        };
        compared += 1;
        let known = KNOWN.iter().chain(KNOWN_UTF8.iter().filter(|_| loc.mb_cur_max() > 1)).find(|(g, _)| *g == line);
        let (want, cat) = match (known, expect.get(line)) {
            (Some((_, ours)), _) => (*ours, None),
            (None, Some((cats, posix))) => (posix.as_str(), Some(cats.clone())),
            (None, None) => (line, None),
        };
        if let Some(cats) = &cat {
            for c in cats.split(',') {
                let (name, n) = c.split_once(':').unwrap();
                *by_cat.entry(name.to_string()).or_default() += n.parse::<usize>().unwrap();
            }
        }
        if ours != want {
            differ.push(format!("record {line}\n  want {want}\n  ours {ours}"));
        }
    }
    eprintln!("regex lines compared: {compared}; POSIX-ruled cases by category: {by_cat:?}");
    for d in differ.iter().take(60) {
        eprintln!("{d}");
    }
    assert!(compared > 12_000, "the record was not read ({compared} lines)");
    assert_eq!(differ.len(), 0, "regex lines that differ from the record and from the POSIX reading");
}
